// Generated by `cargo test` from the Rust types (src-tauri/src/settings.rs,
// `bindings`); don't edit. After changing them, run
// `ANOMP_WRITE_BINDINGS=1 cargo test bindings` in src-tauri.

export type AppSettings = { display: DisplaySettings, playback: PlaybackSettings, output: OutputSettings, visualizer: VisualizerSettings, features: FeatureSettings, equaliser: EqualiserSettings, 
/**
 * X2: the effects' settings, used while `features.effects` is on.
 */
effects: EffectsSettings, library: LibrarySettings, window: WindowSettings, appearance: AppearanceSettings, };

/**
 * The settings, and the defaults a section can be reset to.
 */
export type SettingsPayload = { settings: AppSettings, defaults: AppSettings, };

/**
 * What the library's lists and pages show.
 */
export type DisplaySettings = { 
/**
 * What track lists show besides the title, in order.
 */
trackColumns: Array<TrackColumn>, 
/**
 * What an album's summary line says about its release, in order.
 */
albumFacts: Array<AlbumFact>, 
/**
 * Album descriptions and artist biographies (from Wikipedia).
 */
showDescriptions: boolean, 
/**
 * A "Now Playing" item in the sidebar (the now-playing bar opens the
 * same page either way).
 */
sidebarNowPlaying: boolean, };

export type TrackColumn = "trackNumber" | "artist" | "album" | "albumArtist" | "year" | "genre" | "duration" | "format" | "bitrate" | "sampleRate" | "playCount" | "lastPlayed" | "dateAdded" | "composer" | "rating";

export type AlbumFact = "date" | "label" | "country" | "format" | "type";

export type PlaybackSettings = { replayGain: ReplayGainMode, 
/**
 * dB added to the ReplayGain tags' gains, -15 to 15.
 */
preamp: number, 
/**
 * dB for tracks without ReplayGain tags while it's on, -15 to 15.
 */
untaggedGain: number, 
/**
 * Lowers a track's gain so its tagged peak doesn't clip.
 */
preventClipping: boolean, 
/**
 * Seconds to crossfade between tracks, 0 (off, gapless) to 12; never
 * between tracks of one album (PLAN.md F14).
 */
crossfade: number, };

export type ReplayGainMode = "off" | "track" | "album";

/**
 * Where the audio goes.
 */
export type OutputSettings = { 
/**
 * The output device's name; null for the system's default device.
 * When it isn't there, the default plays until it comes back.
 */
device: string | null, 
/**
 * Samples per block; null for the device's default.
 */
bufferSize: number | null, };

export type VisualizerSettings = { 
/**
 * The visualization's id (`app/src/lib/visualizer`); the frontend
 * shows its first one for an id it doesn't know.
 */
visualization: string, 
/**
 * Which albums the cover wall shows.
 */
coverBasis: CoverBasis, 
/**
 * Analyses a second, 10 to 120.
 */
frameRate: number, 
/**
 * Scales the spectrum, 0.25 to 4.
 */
sensitivity: number, 
/**
 * Colours from the current cover rather than the defaults.
 */
colorsFromCover: boolean, 
/**
 * Moves on to the next visualization this often; 0 never.
 */
cycleSeconds: number, 
/**
 * Calm mode: no beats, slow motion (PLAN.md F18); on by itself while
 * the OS asks for reduced motion.
 */
calm: boolean, };

export type CoverBasis = "year" | "artist";

/**
 * The optional features (PLAN.md §4.6, O1–O19), each of which the user
 * can turn on or off. Local, cheap features are on by default; ones that
 * cost hours of CPU time (the loudness analysis), change what is heard
 * (crossfeed, sample-rate switching, effects), go online (ListenBrainz, update
 * checks) or listen on the network (the remote) are off until the user
 * turns them on.
 */
export type FeatureSettings = { 
/**
 * O1: measures each track's loudness in the background, so tracks
 * without ReplayGain tags are evened out too.
 */
loudnessAnalysis: boolean, 
/**
 * O2: the seek bar draws the track's waveform (once analysed).
 */
waveformSeekBar: boolean, 
/**
 * O3: shuffle keeps tracks that run into each other together, in order.
 */
segueShuffle: boolean, 
/**
 * O3: jumps over long silences, e.g. before a hidden track, after
 * `skip_silence_after` seconds of them.
 */
skipSilence: boolean, 
/**
 * Seconds of silence played before the jump, 1 to 60.
 */
skipSilenceAfter: number, 
/**
 * O4: the library health report.
 */
healthReport: boolean, 
/**
 * O5: single-file albums with a cue sheet, and chaptered files, become
 * a track per cue or chapter.
 */
cueSheets: boolean, 
/**
 * O6: works, movements and composers from the tags.
 */
classical: boolean, 
/**
 * O7: the user's own rules for a track or album (skip, never shuffle,
 * gain, trims).
 */
playbackPreferences: boolean, 
/**
 * O8: keeps a history of what was played, on this computer only.
 */
listeningHistory: boolean, 
/**
 * O8: also sends each listen to ListenBrainz with the user's token.
 */
listenbrainz: boolean, 
/**
 * O9: "Start radio" plays tracks like one, and keeps adding more.
 */
libraryRadio: boolean, 
/**
 * O9: any queue carries on as radio when it runs out.
 */
radioAfterQueue: boolean, 
/**
 * O10: clicking the format in the now-playing bar shows every step to
 * the speakers.
 */
signalPath: boolean, 
/**
 * O10: switches the device to each track's sample rate when it can.
 */
matchSampleRate: boolean, 
/**
 * O11: headphone crossfeed.
 */
crossfeed: CrossfeedLevel, 
/**
 * O11: crossfeed only while the OS says headphones are plugged in.
 */
crossfeedHeadphonesOnly: boolean, 
/**
 * O12: A–B loops and playing slower or faster.
 */
practiceMode: boolean, 
/**
 * O13: lyrics from the tags and `.lrc` files next to the tracks.
 */
lyrics: boolean, 
/**
 * O14: a remote control page for phones on the same network.
 */
remoteControl: boolean, 
/**
 * Its TCP port, 1024 to 65535.
 */
remotePort: number, 
/**
 * O15: the albums added most recently.
 */
recentlyAdded: boolean, 
/**
 * O16: what was played most recently (needs the history).
 */
recentlyPlayed: boolean, 
/**
 * O17: albums released on this day in earlier years.
 */
onThisDay: boolean, 
/**
 * O18: five random albums in the same genre on album pages.
 */
moreInGenre: boolean, 
/**
 * O19: the most played tracks, albums and artists of a year or month
 * (needs the history).
 */
topPlayed: boolean, 
/**
 * Checks the GitHub Releases page for a newer version at launch and
 * daily (`updates`).
 */
updateCheck: boolean, 
/**
 * X1: the user's theme (`appearance`); off, the default theme shows.
 */
themes: boolean, 
/**
 * X2: real-time effects on what is playing (`AppSettings.effects`);
 * off, every effect is off.
 */
effects: boolean, 
/**
 * X4: "More like this" for tracks, albums and artists, and Home's
 * suggestions, from the library alone.
 */
recommendations: boolean, 
/**
 * X5: artists outside the library, from ListenBrainz's similar
 * artists for the MusicBrainz ids of the artists played most, and
 * MusicBrainz's relations.
 */
outsideRecommendations: boolean, };

export type CrossfeedLevel = "off" | "light" | "medium" | "strong";

/**
 * The graphic equaliser (PLAN.md F15): ten bands and a preamp, with a
 * profile for speakers and, if it follows the output, one for headphones.
 */
export type EqualiserSettings = { enabled: boolean, 
/**
 * Used unless `follow_output` is on and headphones are plugged in.
 */
speakers: EqualiserProfile, headphones: EqualiserProfile, 
/**
 * Switches to the headphones profile while the OS says headphones
 * are plugged in.
 */
followOutput: boolean, };

/**
 * Gains for the ten bands (31 Hz to 16 kHz) and a preamp, in dB.
 */
export type EqualiserProfile = { 
/**
 * The preset these came from ("flat", "bassBoost"…), or "custom".
 */
preset: string, preamp: number, gains: Array<number>, };

/**
 * Each effect's settings, by its id in the core.
 */
export type EffectsSettings = { reverb: EffectSettings, chorus: EffectSettings, freeze: EffectSettings, echo: EffectSettings, flanger: EffectSettings, phaser: EffectSettings, tremolo: EffectSettings, lofi: EffectSettings, };

/**
 * One effect: on or off, its wet/dry mix and its parameters by id.
 */
export type EffectSettings = { enabled: boolean, 
/**
 * 0 (the music only) to 1 (the effect only).
 */
mix: number, 
/**
 * Every parameter the core lists for it, within its range.
 */
params: Record<string, number>, };

/**
 * Keeping the library in step with the disk (PLAN.md F9).
 */
export type LibrarySettings = { 
/**
 * Rescans every folder in the background at launch.
 */
rescanAtLaunch: boolean, 
/**
 * Rescans a folder when its files change while the app runs.
 */
watchFolders: boolean, };

/**
 * The app's windows and what it shows outside them (PLAN.md F7, F21).
 */
export type WindowSettings = { 
/**
 * Transport and the current track in the menu bar.
 */
menuBarControls: boolean, 
/**
 * The mini player stays above other windows.
 */
miniPlayerOnTop: boolean, 
/**
 * A notification when the track changes while the window isn't in
 * front, with the cover.
 */
trackNotifications: boolean, 
/**
 * The visualizer's note about flashing lights was read (F18).
 */
visualizerNoteSeen: boolean, };

/**
 * The look of the app.
 */
export type AppearanceSettings = { 
/**
 * The theme in use.
 */
theme: Theme, 
/**
 * The user's themes, by name, at most `MAX_SAVED`.
 */
saved: Array<Theme>, 
/**
 * Uses the high-contrast theme's colours while the system asks for
 * more contrast (F18).
 */
followSystemContrast: boolean, };

/**
 * One theme's tokens.
 */
export type Theme = { 
/**
 * What the user called it; the UI names built-in ones itself.
 */
name: string, 
/**
 * The built-in theme these came from ("system", "dark"…), or "custom".
 */
preset: string, 
/**
 * Which palette shows: the system's choice, or always one.
 */
scheme: Scheme, light: ThemePalette, dark: ThemePalette, font: Font, 
/**
 * The base text size in px, 12 to 22; everything sized in rem follows.
 */
textSize: number, density: Density, 
/**
 * Corner radius in px, 0 to 16.
 */
radius: number, 
/**
 * The accent takes the current cover's main colour, made readable.
 */
accentFromCover: boolean, };

/**
 * A theme's colours, each `#rrggbb`. The names are the CSS custom
 * properties', in camel case.
 */
export type ThemePalette = { bg: string, surface: string, 
/**
 * Raised controls, and hover.
 */
surface2: string, text: string, textMuted: string, 
/**
 * Icons and separators, never text.
 */
textFaint: string, border: string, accent: string, 
/**
 * Text on the accent.
 */
accentText: string, danger: string, heart: string, star: string, };

export type Scheme = "system" | "light" | "dark";

/**
 * The fonts a theme can use; the frontend maps each to a font stack.
 */
export type Font = "system" | "rounded" | "serif" | "mono" | "humanist";

/**
 * How much room lists and controls take.
 */
export type Density = "compact" | "regular" | "roomy";

/**
 * The output devices, and which one plays.
 */
export type OutputStatus = { 
/**
 * Every output device there is now.
 */
devices: Array<string>, 
/**
 * The open device, if any.
 */
current: DeviceInfo | null, 
/**
 * The settings name a device that isn't there: the default plays.
 */
chosenMissing: boolean, };

/**
 * The open output device's settings.
 */
export type DeviceInfo = { name: string, 
/**
 * Samples per block.
 */
bufferSize: number, defaultBufferSize: number, 
/**
 * What the device offers, smallest first.
 */
bufferSizes: Array<number>, 
/**
 * Hz.
 */
sampleRate: number, 
/**
 * Seconds from the player to the speakers.
 */
outputLatency: number, };

export type SortSettings = { 
/**
 * Never empty.
 */
rules: Array<SortRule>, 
/**
 * Words skipped at the start of artist names and album and track titles
 * when sorting (not when displaying), compared ignoring case and
 * accents. Empty turns this off.
 */
ignoredArticles: Array<string>, };

export type SortRule = { 
/**
 * Unique among the rules.
 */
id: string, name: string, levels: Array<Level>, trackOrder: Array<TrackKey>, 
/**
 * Missing in rules saved before it existed.
 */
albumOrder: AlbumOrder, };

/**
 * What tracks are grouped by at one level of a rule.
 */
export type Level = "albumArtist" | "artist" | "album" | "genre" | "year" | "folder" | "composer" | "work";

/**
 * What tracks are sorted by within a group, in order of precedence. Ties
 * left after all of them fall back on the track id.
 */
export type TrackKey = "albumArtist" | "artist" | "album" | "year" | "discNumber" | "trackNumber" | "title" | "path" | "dateAdded" | "movement";

/**
 * How albums are ordered where a rule lists them.
 */
export type AlbumOrder = "title" | "year" | "dateAdded";

export type MetadataSettings = { 
/**
 * Every source this version knows, in the order the UI lists them.
 */
sources: Array<SourceInfo>, settings: ServiceSettings, };

export type ServiceSettings = { 
/**
 * The switch for every online source; local ones are unaffected.
 */
online: boolean, 
/**
 * Look albums up in the background after each scan.
 */
autoMatch: boolean, 
/**
 * One entry per source, in `SourceId::ALL` order.
 */
sources: Array<SourceSettings>, 
/**
 * For each kind, every source that supplies it, in priority order.
 */
order: Record<MetadataKind, Array<SourceId>>, };

export type SourceSettings = { id: SourceId, enabled: boolean, 
/**
 * Whether its key is in the keychain (`keys`). Only `keys::set_key`
 * changes it: saving the settings keeps what was stored.
 */
hasKey: boolean, };

/**
 * What the UI shows about a source.
 */
export type SourceInfo = { id: SourceId, name: string, kinds: Array<MetadataKind>, 
/**
 * Contacts a service over the network, so it obeys the online switch.
 */
online: boolean, 
/**
 * Needs an API key or token from the user before it can be used.
 */
needsKey: boolean, 
/**
 * What the key is called, and where the user gets one.
 */
keyName: string | null, keyUrl: string | null, 
/**
 * On until the user turns it off.
 */
enabledByDefault: boolean, 
/**
 * Its details are kept in the library; otherwise only the match is,
 * and the details are fetched when shown (`metadata_release_details`).
 */
storesDetails: boolean, 
/**
 * Shown next to its data, linked to the page it came from, as its
 * terms require.
 */
credit: string | null, 
/**
 * Shown with the source in the settings, as its terms require.
 */
notice: string | null, 
/**
 * Another source it relies on (the Cover Art Archive needs a
 * MusicBrainz match, and Wikipedia a MusicBrainz artist or album).
 */
requires: SourceId | null, homepage: string | null, 
/**
 * The hosts it contacts, as `metadata-progress` names those that
 * can't be reached.
 */
hosts: Array<string>, };

/**
 * A metadata source. The serialized id is also what the `source` columns
 * of migration 003 store, so it must never change.
 */
export type SourceId = "embedded" | "folder" | "musicbrainz" | "cover-art-archive" | "wikipedia" | "discogs";

/**
 * A kind of data that sources supply.
 */
export type MetadataKind = "release" | "albumArt" | "artistInfo" | "albumInfo";
